class Solution {
    int maxLen = 0;
    public String shortestPalindrome(String s) {
        int n = s.length();
        if (s == null || n == 0) {
            return "";
        }
        int i = 0;
        int end = n - 1;
        int j = end;
        while (i < j) {
            if (s.charAt(i) == s.charAt(j)) {
                i++;
                j--;
            } else {
                i = 0;
                end--;
                j = end;
            }
        }
        if (i == n) {
            return s;
        }
        return new StringBuilder(s.substring(end + 1)).reverse().toString() + s;
    }
}

